private val TRAD_TO_SIMP: Map<Char, Char> by lazy {
    HashMap<Char, Char>(TRAD.length * 2).apply {
        for (i in TRAD.indices) put(TRAD[i], SIMP[i])
    }
}

/**
 * Convert traditional hanzi to simplified so they render in the brush font.
 * Fast-paths pure-Latin text (the common case) with no allocation. Identity
 * for characters with no mapping.
 */
fun simplifyHanzi(text: String): String {
    var hasCjk = false
    for (c in text) if (c.code >= 0x2E80) { hasCjk = true; break }
    if (!hasCjk) return text
    val sb = StringBuilder(text.length)
    var changed = false
    for (c in text) {
        val r = TRAD_TO_SIMP[c]
        if (r != null) { sb.append(r); changed = true } else sb.append(c)
    }
    return if (changed) sb.toString() else text
}
